(()=>{'use strict';for(const z of Object.values(zombieTypes)){z.health=Math.ceil(z.health*1.3);z.maxHealth=z.health}zombieTypes.giant={emoji:'🗿',health:220,maxHealth:220,speed:5,damage:3,points:1500};const container=document.getElementById('gameContainer'),track=document.createElement('div');track.id='campaign-track';track.innerHTML='<span id="campaign-label"></span><div class="campaign-rail"><progress id="campaign-progress" max="1" value="0" aria-label="波數進度"></progress><i style="left:25%">⚑</i><i style="left:50%">⚑</i><i style="left:75%">⚑</i><i style="left:98%">◆</i></div><small id="campaign-next"></small>';container.append(track);
const mowerSVG='<svg viewBox="0 0 64 54" aria-hidden="true"><path d="M42 29L35 7H19" fill="none" stroke="#e8d2a4" stroke-width="5"/><path d="M9 27h42l6 14H4z" fill="#bc5943" stroke="#713b31" stroke-width="3"/><rect x="19" y="16" width="22" height="18" rx="4" fill="#e8b74f" stroke="#805d34" stroke-width="3"/><circle cx="16" cy="44" r="8" fill="#304e42"/><circle cx="47" cy="44" r="8" fill="#304e42"/><circle cx="16" cy="44" r="3" fill="#e3cb8e"/><circle cx="47" cy="44" r="3" fill="#e3cb8e"/></svg>';
function resetMowers(){container.querySelectorAll('.lawnmower').forEach(e=>e.remove());gameState.mowers=GardenRules.mowers();for(const m of gameState.mowers){const el=document.createElement('div');el.className='lawnmower';el.setAttribute('role','img');el.innerHTML=mowerSVG;container.append(el);m.element=el}render()}
function render(){if(!gameState.boardRect)return;for(const m of gameState.mowers||[]){m.element.dataset.state=m.state;m.element.style.left=(gameState.boardRect.left+m.x)+'px';m.element.style.top=(gameState.boardRect.top+(m.row+.5)*gameState.cellSize.height-23)+'px';m.element.setAttribute('aria-label','第'+(m.row+1)+'列割草機，'+({ready:'準備好',active:'啟動',spent:'已用完'})[m.state])}const w=gameState.battle;if(w){document.getElementById('campaign-progress').value=GardenRules.progress(w,gameState.isVictory);document.getElementById('campaign-progress').setAttribute('aria-valuetext','第 '+w.number+' / 20 波');document.getElementById('campaign-label').textContent='第 '+w.number+' / 20 波';document.getElementById('campaign-next').textContent=w.number===20?'最終巨人波':Math.max(0,Math.ceil((GardenRules.DURATION-w.elapsed)/1000))+'s 下一波'}}
spawnZombieWave=function(){if(gameState.waveTimer)clearTimeout(gameState.waveTimer);gameState.waveTimer=null;gameState.waveDuration=GardenRules.DURATION;gameState.battle=GardenRules.wave(gameState.wave);resetMowers();updateWaveDisplay()};scheduleNextWave=function(){};
const previous=window.gardenActiveStep;window.gardenActiveStep=dt=>{previous?.(dt);if(gameState.isGameOver||!gameState.boardRect||!gameState.cellSize?.width)return;if(!gameState.battle)spawnZombieWave();const targets=gameState.zombies.map((z,id)=>({id,row:z.row,x:z.x,alive:!!z.element}));for(const id of GardenRules.stepMowers(gameState.mowers,targets,dt/1000,gameState.boardRect.width)){const z=gameState.zombies[id];if(!z?.element)continue;z.health=0;addScore(zombieTypes[z.type].points);createParticleEffect(z.element,'✦');z.element.remove();z.element=null;gameState.zombiesDefeated++}const alive=gameState.zombies.filter(z=>z.element).length;for(const e of GardenRules.step(gameState.battle,dt,alive)){if(e.type==='spawn')spawnZombie(e.giant?'giant':undefined,e.row);if(e.type==='next'){gameState.wave++;gameState.zombieDamageMultiplier=1+(gameState.wave-1)*.02;gameState.battle=GardenRules.wave(gameState.wave);updateWaveDisplay();updateDamageDisplay();addScore(100*gameState.wave);saveGameState()}if(e.type==='victory')victory()}gameState.waveTimeElapsed=gameState.battle.elapsed;render()};window.addEventListener('resize',render);window.gardenBattleSnapshot=()=>({wave:gameState.battle?{...gameState.battle}:null,progress:gameState.battle?GardenRules.progress(gameState.battle,gameState.isVictory):0,mowers:gameState.mowers?.map(({row,x,state})=>({row,x,state})),giants:gameState.zombies.filter(z=>z.type==='giant'&&z.element).length});})();
